import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<Integer>> answer = new ArrayList<>();
        backtrack(candidates, target, 0, new ArrayList<>(), answer);
        return answer;
    }

    private void backtrack(int[] candidates, int remain, int start, List<Integer> path, List<List<Integer>> answer) {
        if (remain == 0) {
            answer.add(new ArrayList<>(path));
            return;
        }
        for (int i = start; i < candidates.length; i++) {
            if (candidates[i] > remain) {
                break;
            }
            if (i > start && candidates[i] == candidates[i - 1]) {
                continue;
            }
            path.add(candidates[i]);
            backtrack(candidates, remain - candidates[i], i + 1, path, answer);
            path.remove(path.size() - 1);
        }
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        TreeMap<Integer, Integer> counts = new TreeMap<>();
        for (int value : candidates) {
            counts.put(value, counts.getOrDefault(value, 0) + 1);
        }

        List<Integer> values = new ArrayList<>(counts.keySet());
        List<Integer> frequencies = new ArrayList<>();
        for (int value : values) {
            frequencies.add(counts.get(value));
        }

        List<List<Integer>> answer = new ArrayList<>();
        dfs(values, frequencies, 0, target, new ArrayList<>(), answer);
        return answer;
    }

    private void dfs(List<Integer> values, List<Integer> frequencies, int index, int remain,
                     List<Integer> path, List<List<Integer>> answer) {
        if (remain == 0) {
            answer.add(new ArrayList<>(path));
            return;
        }
        if (index == values.size()) {
            return;
        }

        int value = values.get(index);
        int maxCopies = Math.min(frequencies.get(index), remain / value);
        for (int used = 0; used <= maxCopies; used++) {
            for (int copy = 0; copy < used; copy++) {
                path.add(value);
            }
            dfs(values, frequencies, index + 1, remain - used * value, path, answer);
            for (int copy = 0; copy < used; copy++) {
                path.remove(path.size() - 1);
            }
        }
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<Set<List<Integer>>> dp = new ArrayList<>();
        for (int sum = 0; sum <= target; sum++) {
            dp.add(new LinkedHashSet<>());
        }
        dp.get(0).add(new ArrayList<>());

        for (int candidate : candidates) {
            for (int sum = target; sum >= candidate; sum--) {
                List<List<Integer>> previous = new ArrayList<>(dp.get(sum - candidate));
                for (List<Integer> combination : previous) {
                    List<Integer> next = new ArrayList<>(combination);
                    next.add(candidate);
                    dp.get(sum).add(next);
                }
            }
        }
        return new ArrayList<>(dp.get(target));
    }
}

import java.util.*;

class Solution {
    private static class State {
        final int start;
        final int remain;
        final List<Integer> path;

        State(int start, int remain, List<Integer> path) {
            this.start = start;
            this.remain = remain;
            this.path = path;
        }
    }

    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<Integer>> answer = new ArrayList<>();
        Deque<State> stack = new ArrayDeque<>();
        stack.push(new State(0, target, new ArrayList<>()));

        while (!stack.isEmpty()) {
            State state = stack.pop();
            if (state.remain == 0) {
                answer.add(state.path);
                continue;
            }
            for (int i = candidates.length - 1; i >= state.start; i--) {
                if (candidates[i] > state.remain) {
                    continue;
                }
                if (i > state.start && candidates[i] == candidates[i - 1]) {
                    continue;
                }
                List<Integer> next = new ArrayList<>(state.path);
                next.add(candidates[i]);
                stack.push(new State(i + 1, state.remain - candidates[i], next));
            }
        }
        return answer;
    }
}
